21	                    rs.getLong("client_id"), rs.getString("client_name"));
22	
23	    public List<Project> findAll() {
24	        return jdbc.query(
25	                "SELECT p.id, p.name, p.client_id, c.name AS client_name"
26	                        + " FROM projects p JOIN clients c ON p.client_id = c.id"
27	                        + " ORDER BY p.id",
28	                MAPPER);
29	    }
30	
31	    /** Projects done for one client — reused by the client detail view. */
32	    public List<Project> findByClient(long clientId) {
33	        return jdbc.query(
34	                "SELECT p.id, p.name, p.client_id, c.name AS client_name"
35	                        + " FROM projects p JOIN clients c ON p.client_id = c.id"
36	                        + " WHERE p.client_id = ? ORDER BY p.id",
37	                MAPPER, clientId);
38	    }
39	
40	    public Project create(String name, long clientId) {
41	        KeyHolder keys = new GeneratedKeyHolder();
42	        jdbc.update(con -> {
43	            var ps = con.prepareStatement(
44	                    "INSERT INTO projects (name, client_id) VALUES (?, ?)", new String[] {"id"});
45	            ps.setString(1, name);
46	            ps.setLong(2, clientId);
47	            return ps;
48	        }, keys);
49	        String clientName = jdbc.queryForObject(
50	                "SELECT name FROM clients WHERE id = ?", String.class, clientId);
51	        return new Project(keys.getKey().longValue(), name, clientId, clientName);
52	    }
53	}
